"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import styles from "../styles/loading-button.module.css";

type Phase = "idle" | "loading" | "success";

export interface LoadingButtonProps {
  /** Idle label (ignored when children are provided) */
  label?: string;
  /** Custom idle content */
  children?: React.ReactNode;
  /** Text shown next to the spinner while loading */
  loadingLabel?: string;
  /** Text shown next to the check mark on success */
  successLabel?: string;
  /** Simulated work duration in milliseconds (used when onAction is not provided) */
  duration?: number;
  /** How long the success state is held before returning to idle, in milliseconds */
  successHold?: number;
  /** Disable the button */
  disabled?: boolean;
  /** Click handler, called when a new cycle starts */
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  /** Async work that drives the loading state instead of the timer; rejection returns to idle */
  onAction?: () => Promise<unknown>;
  /** Optional className */
  className?: string;
}

function Spinner() {
  return (
    <svg className={styles.spinner} viewBox="0 0 24 24" width="16" height="16" aria-hidden="true">
      <circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" strokeOpacity="0.25" strokeWidth="3" />
      <path d="M21 12a9 9 0 0 0-9-9" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true">
      <path d="M5 12.5l4.5 4.5L19 7.5" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function LoadingButton({
  label = "Deploy to production",
  children,
  loadingLabel = "Deploying",
  successLabel = "Deployed",
  duration = 1600,
  successHold = 1400,
  disabled = false,
  onClick,
  onAction,
  className = "",
}: LoadingButtonProps) {
  const prefersReducedMotion = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("idle");
  const phaseRef = React.useRef<Phase>("idle");
  const timers = React.useRef<number[]>([]);
  const mounted = React.useRef(false);

  React.useEffect(() => {
    mounted.current = true;
    const pending = timers.current;
    return () => {
      mounted.current = false;
      pending.forEach((id) => window.clearTimeout(id));
      pending.length = 0;
    };
  }, []);

  const go = (next: Phase) => {
    if (!mounted.current) return;
    phaseRef.current = next;
    setPhase(next);
  };

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms));
  };

  const succeed = () => {
    go("success");
    later(() => go("idle"), successHold);
  };

  const handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    if (phaseRef.current !== "idle" || disabled) return;
    onClick?.(event);
    go("loading");
    if (onAction) {
      onAction().then(succeed, () => go("idle"));
    } else {
      later(succeed, duration);
    }
  };

  const content =
    phase === "loading" ? (
      <>
        <Spinner />
        {loadingLabel}
      </>
    ) : phase === "success" ? (
      <>
        <CheckIcon />
        {successLabel}
      </>
    ) : (
      children ?? label
    );

  return (
    <motion.button
      type="button"
      layout={!prefersReducedMotion}
      disabled={disabled}
      aria-busy={phase === "loading"}
      aria-live="polite"
      onClick={handleClick}
      data-phase={phase}
      transition={{ type: "spring", stiffness: 420, damping: 34 }}
      className={`${styles.root} ${className}`.trim()}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={phase}
          className={styles.content}
          initial={prefersReducedMotion ? { opacity: 0 } : { y: 18, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={prefersReducedMotion ? { opacity: 0 } : { y: -18, opacity: 0 }}
          transition={{ duration: prefersReducedMotion ? 0 : 0.22, ease: [0.22, 1, 0.36, 1] }}
        >
          {content}
        </motion.span>
      </AnimatePresence>
    </motion.button>
  );
}

.root {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 10rem;
  padding: 0.7rem 1.35rem;
  overflow: hidden;
  border-radius: 0.625rem;
  border: 1px solid var(--mf-fg, #f4f4f6);
  background-color: var(--mf-fg, #f4f4f6);
  color: var(--mf-bg, #09090b);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  user-select: none;
  transition: background-color 200ms ease, border-color 200ms ease, color 200ms ease;
}

.root:hover:not(:disabled)[data-phase="idle"] {
  background-color: #ffffff;
}

.root[data-phase="loading"] {
  cursor: progress;
  background-color: var(--mf-surface-raised, #1b1b22);
  border-color: var(--mf-border, #2e2e38);
  color: var(--mf-fg, #f4f4f6);
}

.root[data-phase="success"] {
  cursor: default;
  background-color: var(--mf-accent, #38bdf8);
  border-color: var(--mf-accent, #38bdf8);
  color: var(--mf-bg, #09090b);
}

.root:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.root:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
}

.content {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
  pointer-events: none;
}

.spinner {
  animation: mfLbSpin 0.8s linear infinite;
}

@keyframes mfLbSpin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .root {
    transition: none;
  }

  .spinner {
    animation-duration: 2.4s;
  }
}

