"use client";

import * as React from "react";
import { AnimatePresence, motion } from "motion/react";

export function LoadingButtonTailwind({ label = "Deploy to production", duration = 1600 }) {
  const [phase, setPhase] = React.useState<"idle" | "loading" | "success">("idle");
  const timers = React.useRef<number[]>([]);
  React.useEffect(() => () => timers.current.forEach(clearTimeout), []);
  const run = () => {
    if (phase !== "idle") return;
    setPhase("loading");
    timers.current.push(window.setTimeout(() => setPhase("success"), duration));
    timers.current.push(window.setTimeout(() => setPhase("idle"), duration + 1400));
  };
  return (
    <motion.button
      type="button"
      layout
      onClick={run}
      aria-busy={phase === "loading"}
      aria-live="polite"
      className={"inline-flex min-w-40 items-center justify-center overflow-hidden rounded-lg px-5 py-2.5 text-sm font-medium " +
        (phase === "loading" ? "bg-zinc-800 text-zinc-100" : phase === "success" ? "bg-sky-400 text-zinc-950" : "bg-zinc-100 text-zinc-950")}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span key={phase} initial={{ y: 18, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: -18, opacity: 0 }} className="inline-flex items-center gap-2">
          {phase === "loading" ? (
            <><span className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />Deploying</>
          ) : phase === "success" ? "Deployed" : label}
        </motion.span>
      </AnimatePresence>
    </motion.button>
  );
}
